tool_input.command:
cat >> db/schema.ts <<'EOF'

// Personal API tokens. Only the SHA-256 of the token is stored; the plain text
// is shown once at creation. The window_* columns hold the per-token
// fixed-window rate limit counter.
export const apiTokens = sqliteTable(
  "api_tokens",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull(),
    name: text("name").notNull(),
    tokenHash: text("token_hash").notNull(),
    createdAt: text("created_at").notNull().default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`),
    windowStart: integer("window_start").notNull().default(0),
    windowCount: integer("window_count").notNull().default(0),
  },
  (t) => [uniqueIndex("api_tokens_token_hash_unique").on(t.tokenHash), index("api_tokens_user_id_idx").on(t.userId)],
);
EOF
sed -i '' 's/import { integer, sqliteTable, text }/import { index, integer, sqliteTable, text, uniqueIndex }/' db/schema.ts
grep -n "uniqueIndex" node_modules/void/dist/*schema-d1* 2>/dev/null | head -3; pnpm exec void db generate 2>&1 | tail -15; git status --short
